import json

# Read current file
with open(r'D:\日语自学网站\src\data\reading-n1.js', 'r', encoding='utf-8') as f:
    content = f.read()

# Find the array start
start = content.index('[')
# Extract existing JSON entries (everything between [ and the last ])
# Since file might not have closing ], find the last complete entry
array_content = content[start+1:]
# Remove trailing whitespace and comma
array_content = array_content.rstrip()
if array_content.endswith(','):
    array_content = array_content[:-1]
if array_content.endswith(']'):
    array_content = array_content[:-1]

# Parse existing entries
existing = json.loads('[' + array_content + ']')
print(f'Existing entries: {len(existing)}')

# Unit 2 data
unit2 = [
  {"id":6,"num":1,"part":"基礎編","unit":2,"unitTitle":"会社・働き方","article":"【1】「とりあえず仕事」をやめるという言葉は、仕事の優先順位を考え抜く仕組みを表すため、自分で作ったものです。【2】すなわち、「とりあえず」というような消極的な仕事をやめて、能動的に仕事を行うべきだという戒めです。【3】この言葉を心がけることで、私は時間を本当に必要なことに使えるようになりました。【4】この言葉が意味するのは、「やっても、やらなくてもいいのだけれども、やらないことによって、場合によっては悪いことが起きるかもしれない。不安だから、保険としてやっておこう」という仕事をしない方がよい、ということです。【5】つまり自分を安心させるために仕事に没頭するわけで、必ずしもその結果を求めているわけではありません。【6】素人と専門家の大きな違いは、専門家ほど、成果とは関係ない余計なことをせず、本当に価値が出るところには逆にこだわりすぎるほどこだわるという選択と集中の仕組みが無意識にできていることなのです。【7】逆に言うと、しっかりした成果を上げるためには、「とりあえず仕事」などやっている暇はないのです。【8】目の前にはいつも、やればやるほど成果が上がる仕事がいくらでも控えているわけですから。【9】20代の駆け出しコンサルタントの頃、上司から口を酸っぱくして言われたのは、「生産性を上げることは、手元の仕事を早く行うことではなく、目的に対して不要な仕事をどんどん削減していく、あるいはやめていくことだ」ということでした。","translation":"第1段指出“放弃姑且做做看的工作态度”这句话是作者为了督促自己合理安排工作顺序而制定的，第2句以「すなわち」引出解释。第2段讲有时候为了保险起见或者让自己心安，人们会去做一些可做可不做的事情，「つまり」是对这段话的总结。第3段讲外行和专业人士的区别在于，越专业的人越不会做与最终结果无关的事情，往往把精力集中在真正有价值的地方。第4段讲作者二十多岁刚从事咨询工作时，曾反复被上司告诫：要想提高业绩，不是靠快速处理手头的工作，而是应该减少或放弃与目的无关的工作。","analysis":[{"sentence":"素人と専門家の大きな違いは、専門家ほど、成果とは関係ない余計なことをせず、本当に価値が出るところには逆にこだわりすぎるほどこだわるという選択と集中の仕組みが無意識にできていることなのです。","note":"句子主干为「素人と専門家の大きな違いは、専門家ほど、…という選択と集中の仕組みが無意識にできていることなのです/外行和专业人士很大的区别在于，越是专业人士，就越会在无意识中计划好了选择和集中做……」。句中有2个「ほど」，前者表示“越……越……”，后者表示程度。"}],"questions":[{"stem":"「とりあえず仕事」をするのは消極的に仕事を進めることだ。","options":["合っている","合っていない"],"answer":0},{"stem":"念のために、やらなくてもいいことをやっておいたほうがいい。","options":["合っている","合っていない"],"answer":1},{"stem":"「とりあえず仕事」をする人は自分を安心させるために仕事に没頭している。","options":["合っている","合っていない"],"answer":0},{"stem":"「とりあえず仕事」をする人はやっている仕事の結果を求めている。","options":["合っている","合っていない"],"answer":1},{"stem":"専門家は余計なことをせず、本当に価値が出るところにこだわっている。","options":["合っている","合っていない"],"answer":0},{"stem":"筆者は専門家の仕事の進め方について、どのように述べているか。","options":["仕事のやり方や経過を問わず、結果だけを求めるようにする。","限られた時間を成果の出る仕事や真の価値のあることに使う。","目の前の仕事とは関係ないことを削除して、計画どおりに仕事を進める。","自分の好きな仕事を積極的に見つけ出して全力を注いでやり抜く。"],"answer":1}]},
  {"id":7,"num":2,"part":"基礎編","unit":2,"unitTitle":"会社・働き方","article":"【1】仕事の遅れを上司に指摘されたとき、「一生懸命にやっているんですが、途中で飛び込みの仕事が入ったりしたものですから、なかなか計画通りにいかなくて…」と言い訳をする人がいます。【2】でも、本当は、計画の立て方そのものに問題があるのです。【3】仕事に雑用や飛び込み仕事、あるいは突発的な事故は付き物です。【4】計画を立てるときには、あらかじめ発生するかもしれない状況を想定し、余裕を持たせるようにすることです。","translation":"文章开头讲了因为工作延误而被上司指责时，有人往往会为自己辩解。「でも」引出作者相反的观点，即真正的原因应该是计划本身有问题。工作中出现杂事、紧急任务和突发状况是很难避免的。文章最后以「〜には〜ことだ」提出建议：在制订计划时就应该把这些因素全都考虑进去。","analysis":[],"questions":[{"stem":"この文章の「中心文」はどれか。","options":["仕事の遅れを上司に指摘されたとき、「一生懸命にやっているんですが…」と言い訳をする人がいます。","でも、本当は、計画の立て方そのものに問題があるのです。","仕事に雑用や飛び込み仕事、あるいは突発的な事故は付き物です。","計画を立てるときには、あらかじめ発生するかもしれない状況を想定し、余裕を持たせるようにすることです。"],"answer":3},{"stem":"仕事が遅いと上司に言われたとき、原因を詳しく説明したほうがいい。","options":["合っている","合っていない"],"answer":1},{"stem":"途中で急な仕事が入って、計画通りに進まなくてもしかたがない。","options":["合っている","合っていない"],"answer":1},{"stem":"急な仕事が入るとうまく処理できない人は、その計画の立て方がよくない。","options":["合っている","合っていない"],"answer":0},{"stem":"仕事に雑用や飛び込み仕事などが入るのはよく起こることだ。","options":["合っている","合っていない"],"answer":0},{"stem":"この文章で筆者が最も言いたいことは何か。","options":["仕事が計画通りに進んでいない場合も言い訳をすべきではない。","仕事の計画の立て方として、雑用や突発的な事故を防ぐことを工夫すべきだ。","仕事の計画を立てる場合、事前に起こりうる状況を設定して考えることが大事だ。","仕事の雑務や突発的な事故などを事前に解決することで、余裕を持って仕事ができる。"],"answer":2}]},
  {"id":8,"num":3,"part":"基礎編","unit":2,"unitTitle":"会社・働き方","article":"【1】組織にいた時は自信あふれる仕事をしていて、その自信からベンチャービジネスを立ち上げたり、フリーランスになったりしたところ、途端に何も仕事ができなくなる人は少なくない。【2】組織の力を最大限に使った仕事をしていると、組織を離れた時に、何もできない人間になる。【3】もし、将来、独立することを考えている人がいたら、巨大な組織にいるときこそ、組織の力を最小限に使って、自分の能力を高めることに力を入れたほうが良い。【4】組織の力だけで業績を上げられる人はほかにもいるし、そういう人は独立する必要がない。","translation":"前两句讲了有不少人在组织中工作时很自信，但是一旦离开组织自己去创业或者成为自由职业者时就发现自己什么也做不了。第3句提出自己的看法，即今后想自己创业的人，应该尽量少借助组织的力量，着力于提升自己。最后一句的「〜し、〜必要がない」用于阐述理由，即有些人光靠组织的力量就可以做出成绩，这种人没必要离开组织。","analysis":[],"questions":[{"stem":"この文章の「中心文」はどれか。","options":["組織にいた時は自信あふれる仕事をしていて…途端に何も仕事ができなくなる人は少なくない。","組織の力を最大限に使った仕事をしていると、組織を離れた時に、何もできない人間になる。","もし、将来、独立することを考えている人がいたら…自分の能力を高めることに力を入れたほうが良い。","組織の力だけで業績を上げられる人はほかにもいるし、そういう人は独立する必要がない。"],"answer":2},{"stem":"組織にいた時自信満々で仕事をしていた人は、独立しても成功する。","options":["合っている","合っていない"],"answer":1},{"stem":"独立する前に、できるだけ組織の力に頼るようにすることだ。","options":["合っている","合っていない"],"answer":1},{"stem":"組織での肩書が立派で有能な人であれば、いつ組織を離れてもいい。","options":["合っている","合っていない"],"answer":1},{"stem":"組織の力でしか仕事ができない人は、独立する必要がない。","options":["合っている","合っていない"],"answer":0},{"stem":"この文章で筆者が最も言いたいことは何か。","options":["独立したいなら、組織の力を最小限に、個人の力を最大限に発揮すべきだ。","大きな組織にいた人ほど組織を離れると、自分の能力が発揮できなくなる。","組織の力を借りて業績を伸ばし、物事を成就させるのが成功の近道である。","ベンチャービジネスを起こすためには、個人の能力を高めることが必要だ。"],"answer":0}]},
  {"id":9,"num":4,"part":"基礎編","unit":2,"unitTitle":"会社・働き方","article":"【1】日本でもサービス業を中心に仕事のマニュアルをつくることが広がってきましたが、マニュアル先進国のアメリカでは、サービス業以外でも多様なマニュアルがあります。【2】新しく採用された人は、仕事全体の流れを理解していなくても、採用された日からマニュアルに沿って担当の仕事を進められるようになっています。【3】アメリカがマニュアル社会になった背景には、多様な出身地、民族などが職場に混在していること、そのうえに頻繁な転職があります。【4】「この仕事はあの人しかできない」という職場では、その人がいなくなってしまったら、仕事全体の流れが止まってしまいます。【5】誰でもすぐ代わりが務まるシステムが不可欠です。【6】誰でもできる代わりのある仕事、マニュアル通りにこなせばよい仕事の報酬は、どんどん下がっていきます。【7】高い報酬を取ろうと思えば、マニュアルを作る仕事か、マニュアルのない仕事につかなければならなくなっています。【8】これに対して、多くの日本の企業は、先輩から後輩に仕事が伝えられていくことを前提としています。【9】新入社員は先輩のやっていることを見様見真似で覚え、技を盗んでいくうちに、やがて一人前になっていくとされます。【10】つまり仕事も「以心伝心」なのです。【11】おそらく職人を長期的に育てるには、日本のやり方のほうがいいでしょう。【12】熟練の達人の仕事には明確な言葉で表現しにくいコツがありますが、こうした暗黙知は経験的に覚えていくしかありません。","translation":"第1段讲了虽然日本以服务业为中心已经形成了标准化的工作流程，但在美国标准化流程更为普及。第2段讲了美国成为标准化流程社会的背景。第3段讲了如果某份工作只有一个人能做，当他离开时整个工作就无法进行，所以要建立一个不管是谁都能迅速顶替的体系。第4段讲了标准化流程的工作与高收入成反比，要获得高收入就要从事创建流程的工作或没有流程可依循的工作。最后一段介绍了日企中老员工带新人的工作方式，并认为这种培养方式更好。","analysis":[{"sentence":"アメリカがマニュアル社会になった背景には、多様な出身地、民族などが職場に混在していること、そのうえに頻繁な転職があります。","note":"句子主干为「…背景には、…こと、そのうえに…があります/……的背景中有……以及……（的因素）」。「アメリカがマニュアル社会になった」修饰「背景」，「多様な出身地、民族などが職場に混在していること」与「頻繁な転職」是并列关系。"}],"questions":[{"stem":"職場ではマニュアルがなければ、仕事全体が止まってしまう恐れがある。","options":["合っている","合っていない"],"answer":0},{"stem":"アメリカでは、新人は採用される前にマニュアルを学ばなければならない。","options":["合っている","合っていない"],"answer":1},{"stem":"多人種の職場と頻繁な転職で、アメリカはマニュアル社会になった。","options":["合っている","合っていない"],"answer":0},{"stem":"高い報酬を取ろうと思えば、マニュアル通りにこなせばよい。","options":["合っている","合っていない"],"answer":1},{"stem":"マニュアルの普及に伴って、「以心伝心」のやり方は通用できなくなってきた。","options":["合っている","合っていない"],"answer":1},{"stem":"筆者の主張と合っているものはどれか。","options":["マニュアルの普及に伴って、「以心伝心」などの暗黙の了解は日本の職場ではだんだん通用できなくなってきた。","仕事の報酬はマニュアルがあるかどうかと比例するので、マニュアルを把握してからやっと一人前になれる。","言葉やマニュアルで表すことのできない職種は時間をかけて少しずつそのコツを身につけるしかない。","社員の流動性の高い業界ではマニュアルがあると便利だが、達人を育てることはできない。"],"answer":2}]},
  {"id":10,"num":5,"part":"基礎編","unit":2,"unitTitle":"会社・働き方","article":"【1】人間の営みである以上、①経営もまた人間に共通する法則が見出されるものだ。【2】昨今の特に若い経営者を見ていて感じるのは、能力的には優秀なのだが、どうも人間としての「知恵」を軽視し、暴走してしまうという一面があるのではないだろうか。【3】ひらたく言えば、昔から腹八分というが、暴飲暴食の経営は長持ちしない。【4】人間の体のように、経営もまた健康管理に気をつけなければいけないのである。【5】松下幸之助は無理を嫌った。【6】「きみ、無理はあかん、無理したらあかんよ」と、私はよく教えられたものだ。【7】松下が成功したのは、無理をせず、経営のすべての面で「ゆとりの経営」を実践したからということも大きな理由だろう。【8】それを松下の造語で言えば②「ダム経営」である。【9】水が涸れたら放水量を増やし、増えたら減らすダムのように、ダムの機能を経営の場に持とうということである。【10】経営を身の丈以上に展開してはいけない。【11】自己資金を貯え、貯えた見合いに応じて拡大していく。【12】工場のような設備も同様だ。【13】一割の余裕設備を持っていれば、急に需要が増えてもすぐに対応できる。【14】品物が余り過ぎるようだったら、設備を少し余計に休めればよい。【15】在庫も同様である。【16】このようにすれば供給や価格も安定し、したがって経営も安定してくる。【17】ひいてはそれが、社会に真の安定的繁栄をもたらすものとして、③松下はダム経営を主張したのである。","translation":"第1段讲了经营是人类的行为，所以对人类行为适用的法则也同样适用于经营。第2段列举了“饭吃八分饱”“不能暴饮暴食”的道理，提出对待经营也应该像对待身体一样要注意健康管理。第3段讲了松下幸之助倾向宽松经营的方式，即第4段提到的“水坝式经营”——枯水季节适当放水，水量过大时减少流量。第5段阐述了“水坝式经营”的合理性：经营规模不宜超过自身能力，商品库存和设备也要留一部分以备不时之需，这样经营才会稳定，从而带来社会的繁荣。","analysis":[{"sentence":"昨今の特に若い経営者を見ていて感じるのは、能力的には優秀なのだが、どうも人間としての「知恵」を軽視し、暴走してしまうという一面があるのではないだろうか。","note":"句子主干为「…のは、…という一面があるのではないだろうか/……是有……的一面，难道不是吗？」。「昨今の…感じる」修饰形式体言「の」，「〜のは」用于提示主题。「能力的には優秀なのだが…暴走してしまう」为「一面」的内容，「〜のではないだろうか」表示作者的看法或主张。"}],"questions":[{"stem":"①経営もまた人間に共通する法則とは会社も人間同様に、健全かつ余裕のある経営が望ましいということだ。","options":["合っている","合っていない"],"answer":0},{"stem":"能力はあるが、経営者としての知識を持っていない若い経営者が多い。","options":["合っている","合っていない"],"answer":1},{"stem":"松下さんは無理をせず、経営の面で「ゆとりの経営」を実践したから成功した。","options":["合っている","合っていない"],"answer":0},{"stem":"②「ダム経営」とは供給のバランスを維持するために、設備の稼動や在庫数を調節する経営方式だ。","options":["合っている","合っていない"],"answer":0},{"stem":"会社の能力以上に経営を拡大すれば、もっと大きな利益を上げることができる。","options":["合っている","合っていない"],"answer":1},{"stem":"③松下はダム経営を主張したのはなぜか。","options":["ダム経営を実施すれば、経営が安定化するだけでなく社会の繁栄にもつながるから","ダム経営を実施することで、資金も設備も順調に回り利益をもたらしてくれるから","ダム経営の方式で、会社の経営が軌道に乗り、激しい競争の中でも生き残れるから","ダム経営を続けることで、自己資金と設備が増え続け、経営規模が拡大できるから"],"answer":0}]}
]

all_data = existing + unit2
print(f'Total entries: {len(all_data)}')

# Write output
lines = []
lines.append('// 读解题库（N1）：橙宝书《新日本语能力考试N1读解》· 基础编')
lines.append('// - 每篇文章：article（【n】为句号标记，渲染为上标）、translation（全文翻译/文章概要）、analysis（难句分析）')
lines.append('// - 判断题已转为两个选项的选择题（合っている / 合っていない）')
lines.append('// - 语汇/语法预习（読む前に）与改写题不收录')
lines.append('// - 振假名由 scripts/gen_reading_furigana.mjs 自动生成，请勿手改')
lines.append('export const readingN1 = [')
for r in all_data:
    lines.append('  ' + json.dumps(r, ensure_ascii=False) + ',')
lines.append(']')

with open(r'D:\日语自学网站\src\data\reading-n1.js', 'w', encoding='utf-8') as f:
    f.write('\n'.join(lines) + '\n')

print('Written successfully')
